interface PublicFooterProps {
  isLoggedIn?: boolean;
}

export function PublicFooter({ isLoggedIn = false }: PublicFooterProps) {
  const pathname = usePathname();

  const authItem = isLoggedIn
    ? { href: "/admin/carteira", label: "Carteira", icon: Wallet }
    : { href: "/login", label: "Login", icon: LogIn };

  const navItems = [...PUBLIC_NAV_ITEMS, authItem];

  return (
    <footer className="pointer-events-none fixed bottom-0 inset-x-0 z-40 h-48 sm:h-72 select-none">
      <div
        aria-hidden="true"
        className="absolute inset-x-0 bottom-0 h-[58%] bg-gradient-to-t from-[#090303] via-[#090303] to-transparent"
      />

      <div
        aria-hidden="true"
        className="absolute inset-0 flex justify-center"
        style={{
          WebkitMaskImage:
            "linear-gradient(to bottom, transparent 0%, rgba(0,0,0,0.65) 14%, black 32%)",
          maskImage:
            "linear-gradient(to bottom, transparent 0%, rgba(0,0,0,0.65) 14%, black 32%)",
        }}
      >
        {/* Camada 2: Encerra a ilustração exatamente nas linhas vermelhas (árvore até lança) */}
        <div
          className="h-full w-full max-w-[1060px] [--fade-start:0%] [--fade-end:6%] sm:[--fade-start:17%] sm:[--fade-end:22%]"
          style={{
            WebkitMaskImage:
              "linear-gradient(to right, transparent 0%, transparent var(--fade-start), black var(--fade-end), black calc(100% - var(--fade-end)), transparent calc(100% - var(--fade-start)), transparent 100%)",
            maskImage:
              "linear-gradient(to right, transparent 0%, transparent var(--fade-start), black var(--fade-end), black calc(100% - var(--fade-end)), transparent calc(100% - var(--fade-start)), transparent 100%)",
          }}
        >
          <svg
            viewBox="0 0 1440 390"
            preserveAspectRatio="xMidYMax slice"
            className="h-full w-full"
          >
            <defs>
              {/* Aura externa difusa das labaredas */}
              <linearGradient id="flameAuraGrad" x1="0" y1="1" x2="0" y2="0">
                <stop offset="0%" stopColor="#FF5514" stopOpacity="0.95" />
                <stop offset="55%" stopColor="#FF8C2B" stopOpacity="0.75" />
                <stop offset="100%" stopColor="#FF4514" stopOpacity="0" />
              </linearGradient>

              {/* Corpo intermediário das chamas */}
              <linearGradient id="flameMidGrad" x1="0" y1="1" x2="0" y2="0">
                <stop offset="0%" stopColor="#FF771C" />
                <stop offset="60%" stopColor="#FFB340" />
                <stop offset="100%" stopColor="#FF661A" stopOpacity="0.45" />
              </linearGradient>

              {/* Núcleo incandescente */}
              <linearGradient id="flameCoreGrad" x1="0" y1="1" x2="0" y2="0">
                <stop offset="0%" stopColor="#FFF9D2" />
                <stop offset="65%" stopColor="#FFDC73" />
                <stop offset="100%" stopColor="#FF9C33" />
              </linearGradient>

              <filter
                id="softFlameBlur"
                x="-15%"
                y="-15%"
                width="130%"
                height="130%"
              >
                <feGaussianBlur stdDeviation="2.6" />
              </filter>
            </defs>
            <path
              fill="url(#flameAuraGrad)"
              filter="url(#softFlameBlur)"
              d={FLAME_AURA_PATH}
            />

            {/* Camada 2: Línguas de fogo principais */}
            <path fill="url(#flameMidGrad)" d={FLAME_MID_PATH} />

            {/* Camada 3: Núcleo brilhante */}
            <path fill="url(#flameCoreGrad)" d={FLAME_CORE_PATH} />
            {/* Fagulhas subindo acima da fogueira */}
            <g fill="#FFB84D">
              <circle cx="712" cy="88" r="1.4" opacity="0.85" />
              <circle cx="728" cy="74" r="1.1" opacity="0.75" />
              <circle cx="704" cy="62" r="1.2" opacity="0.6" />
              <circle cx="721" cy="48" r="1.5" opacity="0.5" />
              <circle cx="735" cy="96" r="1.3" opacity="0.8" />
              <circle cx="698" cy="105" r="1.1" opacity="0.7" />
              <circle cx="716" cy="32" r="1.0" opacity="0.35" />
            </g>

            {/* Silhueta principal em curvas suaves */}
            <path fill="#090303" fillRule="evenodd" d={SILHOUETTE_PATH} />
          </svg>
        </div>
      </div>

      <nav
        aria-label="Navegação principal"
        className="pointer-events-auto absolute inset-x-0 bottom-0 z-10 mx-auto flex h-14 sm:h-16 max-w-5xl items-center justify-center gap-0.5 px-2 sm:gap-4"
      >
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive =
            item.href === "/"
              ? pathname === "/"
              : pathname === item.href || pathname.startsWith(`${item.href}/`);

          return (
            <Link
              key={item.href}
              href={item.href}
              title={item.label}
              aria-label={item.label}
              className={`group relative flex flex-row items-center justify-center gap-2 rounded-xl px-2 py-1.5 transition-all duration-200 sm:px-3 ${
                isActive
                  ? "bg-[#F28C38]/20 text-[#FAF6F0] ring-1 ring-[#F28C38]/30"
                  : "text-[#F4ECE1]/70 hover:bg-[#F28C38]/12 hover:text-[#FAF6F0]"
              }`}
            >
              <Icon
                className="size-4 sm:size-[18px]"
                strokeWidth={isActive ? 2.25 : 1.75}
              />
              <span className="text-[14px] font-medium leading-none">
                {item.label}
              </span>
            </Link>
          );
        })}
      </nav>
    </footer>
  );
}